114	    /**
115	     * A claim's due on the sheet's today: the due fixed when settled, else its figure with its late
116	     * charge added on top, raised to the floor (see {@link LateCharge}); null when it has none.
117	     */
118	    public BigDecimal charged(String sheetId, Person person, Claim claim) {
119	        if (isFrozen(claim)) {
120	            return claim.getSettledDue();
121	        }
122	        return LateCharge.withCharge(sheets.sheet(sheetId), claim, figure(sheetId, person, claim));
