186	    /**
187	     * Open a claim's editor: the claim is locked for every other user until the editor is saved or
188	     * cancelled, or the sheet's today changes. Refused (403) for a viewer, (409) for a claim that is
189	     * not DRAFT or is locked by another user, and (423) when dated inside a closed period; a refused
190	     * claim takes no lock. Any other claim of the same person the user had locked is released.
191	     */
192	    @Transactional
193	    public Claim lock(String sheetId, String user, long id) {
194	        roles.refuseViewer(sheetId, user);
195	        // hold the sheet so two users cannot both take the lock
196	        sheets.lock(sheetId);
197	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
198	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
199	        refuseIfNotEditable(sheetId, user, claim);
200	        periods.refuseIfClosed(sheetId, claim.getDate());
201	        for (Claim other : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId())) {
202	            if (other.getId() != id && user.equals(other.getLockedBy())) {
203	                other.setLockedBy(null);
204	                claims.save(other);
205	            }
206	        }
207	        claim.setLockedBy(user);
208	        return claims.saveAndFlush(claim);
209	    }
