211	    /** Cancel a claim's editor: the user's lock on the claim is released; another user's lock stays. */
212	    @Transactional
213	    public Claim unlock(String sheetId, String user, long id) {
214	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
215	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
216	        if (user.equals(claim.getLockedBy())) {
217	            claim.setLockedBy(null);
218	            claim = claims.saveAndFlush(claim);
219	        }
220	        return claim;
221	    }
