265	    /** Move a claim to a new status; {@code review} for a steward's approval or rejection of a PENDING claim. */
266	    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason,
267	            boolean review) {
268	        roles.refuseViewer(sheetId, user);
269	        if (!review) {
270	            roles.refuseUnlessPermitted(sheetId, user, switch (next) {
271	                case OPEN -> "open";
272	                case SETTLED -> "settle";
273	                case VOID -> "void";
274	                default -> throw new IllegalStateException();
275	            });
276	        }
277	        // lock the sheet's numbering before reading the claim, so a claim is opened (and numbered) once
278	        if (next == ClaimStatus.OPEN) {
279	            sheets.lock(sheetId);
280	        }
281	        RollupService.Snapshot before = rollup.snapshot(sheetId);
282	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
283	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
284	        ClaimStatus was = claim.getStatus();
285	        // only a steward's review moves a PENDING claim on, other than voiding it
286	        if (!was.canBecome(next) || (next != ClaimStatus.VOID && review != (was == ClaimStatus.PENDING))) {
287	            throw new ResponseStatusException(HttpStatus.CONFLICT,
288	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
289	        }
290	        periods.refuseIfClosed(sheetId, claim.getDate());
291	        boolean reversing = was == ClaimStatus.SETTLED;
292	        if (reversing) {
293	            refuseVoidSettled(sheetId, user, claim);
294	        }
295	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
296	            throw new ResponseStatusException(HttpStatus.CONFLICT,
297	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then.");
298	        }
299	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
300	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
301	                    "The user who opened a claim cannot " + (review ? "approve" : "settle") + " it.");
302	        }
303	        if (review && !isSteward(sheetId, user)) {
304	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
305	                    "Only a steward can approve or reject a PENDING claim.");
306	        }
307	        Person person = person(sheetId, claim.getPersonId());
308	        if (next == ClaimStatus.OPEN && !review && needsNote(sheetId, person, claim)) {
309	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
310	                    "A claim due above the note threshold cannot be opened with an empty note.");
311	        }
312	        // settling fixes the figure with its late charge as it stands on the sheet's today (a
313	        // PENDING claim's figure is live)
314	        BigDecimal settling = next == ClaimStatus.SETTLED ? charged(sheetId, person, claim) : null;
315	        if (next == ClaimStatus.SETTLED && needsProof(sheetId, claim, settling)) {
316	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
317	                    "A claim due above the proof threshold cannot be " + (review ? "approved" : "settled")
318	                            + " without a proof.");
319	        }
320	        if (next == ClaimStatus.SETTLED && !review && aboveClerkLimit(sheetId, user, settling)) {
321	            next = ClaimStatus.PENDING;
322	            settling = null;
323	        }
324	        claim.setStatus(next);
325	        if (next == ClaimStatus.OPEN && !review) {
326	            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDate()));
327	            claim.setOpenedBy(user);
328	        } else if (next == ClaimStatus.SETTLED) {
329	            claim.setSettledDue(settling);
330	        }
331	        logStatus(sheetId, user, person, claim);
332	        Claim saved = claims.saveAndFlush(claim);
333	        String event = switch (next) {
334	            case OPEN -> review ? "CLAIM_REJECTED" : "CLAIM_OPENED";
335	            case PENDING -> "CLAIM_PENDING";
336	            case SETTLED -> review ? "CLAIM_APPROVED" : "CLAIM_SETTLED";
337	            case VOID -> "CLAIM_VOIDED";
338	            case DRAFT -> throw new IllegalStateException();
339	        };
340	        audit.recordOnCommit(record(event, sheetId, user, person, saved)
341	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
342	                + (next == ClaimStatus.SETTLED ? " due=" + dueText(saved.getSettledDue()) : "")
343	                + (reason != null ? " reason=" + reason : "")
344	                + (reversing ? " reversed=" + dueText(saved.getSettledDue()) : ""));
345	        if (next == ClaimStatus.SETTLED) {
346	            notifyWatchers(sheetId, user, person, saved);
347	        }
348	        rollup.recordChanges(sheetId, user, before);
349	        return saved;
350	    }
