352	    /**
353	     * Refuse voiding a SETTLED claim: (403) for anyone but a steward, and (409) once the sheet's
354	     * today is more than {@value #VOID_SETTLED_DAYS} days after its settlement (or before it).
355	     */
356	    private void refuseVoidSettled(String sheetId, String user, Claim claim) {
357	        if (!isSteward(sheetId, user)) {
358	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can void a SETTLED claim.");
359	        }
360	        LocalDate settled = claim.getLog().stream().filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
361	                .map(ClaimLogEntry::getDate).reduce((first, last) -> last).orElse(null);
362	        LocalDate today = sheets.today(sheetId);
363	        if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
364	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A SETTLED claim can be voided only within "
365	                    + VOID_SETTLED_DAYS + " days of its settlement.");
366	        }
367	    }
