377	    /**
378	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it
379	     * the claim counts in no total, is not overdue and cannot be settled; a statement it is bound
380	     * by stays as it is. Refused (409) for a claim that is not OPEN, (400) for a date
381	     * not after the sheet's today and (423) when dated inside a closed period.
382	     */
383	    @Transactional
384	    public Claim defer(String sheetId, String user, long id, LocalDate until) {
385	        roles.refuseViewer(sheetId, user);
386	        RollupService.Snapshot before = rollup.snapshot(sheetId);
387	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
388	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
389	        if (claim.getStatus() != ClaimStatus.OPEN) {
390	            throw new ResponseStatusException(HttpStatus.CONFLICT,
391	                    "A " + claim.getStatus() + " claim cannot be deferred.");
392	        }
393	        if (!until.isAfter(sheets.today(sheetId))) {
394	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
395	                    "A claim can only be deferred to a date after the sheet's today.");
396	        }
397	        periods.refuseIfClosed(sheetId, claim.getDate());
398	        Person person = person(sheetId, claim.getPersonId());
399	        claim.setDeferredUntil(until, sheets.today(sheetId));
400	        Claim saved = claims.saveAndFlush(claim);
401	        audit.recordOnCommit(record("CLAIM_DEFERRED", sheetId, user, person, saved)
402	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "") + " until=" + until);
403	        rollup.recordChanges(sheetId, user, before);
404	        return saved;
405	    }
