416	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
417	            throw new ResponseStatusException(HttpStatus.CONFLICT,
418	                    "A " + claim.getStatus() + " claim cannot have a proof added.");
419	        }
420	        periods.refuseIfClosed(sheetId, claim.getDate());
421	        Person person = person(sheetId, claim.getPersonId());
422	        claim.addProof();
423	        Claim saved = claims.saveAndFlush(claim);
424	        audit.recordOnCommit(record("CLAIM_PROOF_ADDED", sheetId, user, person, saved)
425	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "") + " proofs=" + saved.getProofs());
