429	    /**
430	     * Re-settle a SETTLED claim: fix its due again at the figure it would have on the sheet's today
431	     * as an open claim bound by no statement, with its late charge. Refused (403) for anyone but a
432	     * steward, (409) for a claim that is not SETTLED and (423) when dated inside a closed period.
433	     */
434	    @Transactional
435	    public Claim resettle(String sheetId, String user, long id) {
436	        roles.refuseViewer(sheetId, user);
437	        if (!isSteward(sheetId, user)) {
438	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim.");
439	        }
440	        RollupService.Snapshot before = rollup.snapshot(sheetId);
441	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
442	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
443	        if (claim.getStatus() != ClaimStatus.SETTLED) {
444	            throw new ResponseStatusException(HttpStatus.CONFLICT,
445	                    "A " + claim.getStatus() + " claim cannot be re-settled.");
446	        }
447	        periods.refuseIfClosed(sheetId, claim.getDate());
448	        Person person = person(sheetId, claim.getPersonId());
449	        BigDecimal old = claim.getSettledDue();
450	        BigDecimal settling = LateCharge.withChargeAsOpen(sheets.sheet(sheetId), claim, due(sheetId, person, claim));
451	        claim.setSettledDue(settling);
452	        logStatus(sheetId, user, person, claim);
453	        Claim saved = claims.saveAndFlush(claim);
454	        audit.recordOnCommit(record("CLAIM_RESETTLED", sheetId, user, person, saved)
455	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
456	                + " old=" + dueText(old) + " new=" + dueText(settling));
457	        notifyWatchers(sheetId, user, person, saved);
458	        rollup.recordChanges(sheetId, user, before);
459	        return saved;
460	    }
