462	    /**
463	     * Re-date an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure bound by a
464	     * statement stays bound; its period follows the new date. Under numbering per period, a claim
465	     * whose period changes takes the next number of its new period's sequence (or the X sequence in
466	     * no period); its old number is never given again. Refused (403) for anyone but a steward, (409)
467	     * for a claim that is not OPEN or PENDING, (423) when dated, or re-dated, inside a closed period
468	     * and (422) for a date after its person's retirement date.
469	     */
470	    @Transactional
471	    public Claim redate(String sheetId, String user, long id, LocalDate date) {
472	        roles.refuseViewer(sheetId, user);
473	        if (!isSteward(sheetId, user)) {
474	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-date a claim.");
475	        }
476	        // lock the sheet's numbering before reading the claim, as opening one does
477	        Sheet sheet = sheets.lock(sheetId);
478	        RollupService.Snapshot before = rollup.snapshot(sheetId);
479	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
480	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
481	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
482	            throw new ResponseStatusException(HttpStatus.CONFLICT,
483	                    "A " + claim.getStatus() + " claim cannot be re-dated.");
484	        }
485	        LocalDate old = claim.getDate();
486	        periods.refuseIfClosed(sheetId, old);
487	        periods.refuseIfClosed(sheetId, date);
488	        Person person = person(sheetId, claim.getPersonId());
489	        refuseIfRetired(person, date);
490	        boolean renumber = sheet.numbersByPeriod()
491	                && !periods.periodNameOn(sheetId, old).equals(periods.periodNameOn(sheetId, date));
492	        claim.setDate(date);
493	        if (renumber) {
494	            claim.setNumber(sheets.nextClaimNumber(sheetId, date));
495	        }
496	        Claim saved = claims.saveAndFlush(claim);
497	        audit.recordOnCommit(record("CLAIM_REDATED", sheetId, user, person, saved)
498	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
499	                + " old=" + old + " new=" + date);
500	        rollup.recordChanges(sheetId, user, before);
501	        return saved;
502	    }
