504	    /**
505	     * Move a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and
506	     * date, is unbound from any statement (live again until its new person's next statement), and
507	     * is listed first under its new person. Refused (403) for a role the permission matrix does not allow, (409) for a SETTLED or VOID
508	     * claim or a move to the person it is already on, (400) for a correction (it must stay with
509	     * the claim it corrects), (423) when dated inside a closed period and (422) when dated after
510	     * the new person's retirement date.
511	     */
512	    @Transactional
513	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
514	        roles.refuseUnlessPermitted(sheetId, user, "reassign");
515	        RollupService.Snapshot before = rollup.snapshot(sheetId);
516	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
517	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
518	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
519	            throw new ResponseStatusException(HttpStatus.CONFLICT,
520	                    "A " + claim.getStatus() + " claim cannot be moved.");
521	        }
522	        Person from = person(sheetId, claim.getPersonId());
523	        Person to = person(sheetId, toPersonId);
524	        if (from.getId().equals(to.getId())) {
525	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is already on that person.");
526	        }
527	        if (claim.isCorrection()) {
528	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A correction cannot be moved.");
529	        }
530	        periods.refuseIfClosed(sheetId, claim.getDate());
531	        refuseIfRetired(to, claim.getDate());
532	        claim.setPersonId(to.getId());
533	        claim.bind(false, null);
534	        claims.saveAndFlush(claim);
535	        claims.listFirst(claim.getId());
536	        Claim saved = claims.findByIdAndSheetId(id, sheetId).orElseThrow();
537	        audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
538	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
539	                + " from=" + from.getName() + " to=" + to.getName());
540	        rollup.recordChanges(sheetId, user, before);
541	        return saved;
542	    }
