548	    /**
549	     * Split an amount off an OPEN claim: the claim keeps the rest of its amount and is unbound from
550	     * any statement; a new OPEN claim with the amount split off, the same date and note, the next
551	     * number, opened by the user and due by its date plus the terms in force on it, is listed first
552	     * under the person and shows the original's number as split-from. Refused (403) for a role that
553	     * may not open a claim, (409) for a claim that is not OPEN or is deferred, (400) for an amount
554	     * not above 0.00 and below the claim's, and (423) when dated inside a closed period.
555	     */
556	    @Transactional
557	    public Split split(String sheetId, String user, long id, BigDecimal amount) {
558	        roles.refuseViewer(sheetId, user);
559	        roles.refuseUnlessPermitted(sheetId, user, "open");
560	        // lock the sheet's numbering before reading the claim, as opening one does
561	        sheets.lock(sheetId);
562	        RollupService.Snapshot before = rollup.snapshot(sheetId);
563	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
564	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
565	        if (claim.getStatus() != ClaimStatus.OPEN) {
566	            throw new ResponseStatusException(HttpStatus.CONFLICT,
567	                    "A " + claim.getStatus() + " claim cannot be split.");
568	        }
569	        if (claim.isDeferredOn(sheets.today(sheetId))) {
570	            throw new ResponseStatusException(HttpStatus.CONFLICT,
571	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be split before then.");
572	        }
573	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
574	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
575	                    "A split must be more than 0.00 and less than the claim's amount.");
576	        }
577	        periods.refuseIfClosed(sheetId, claim.getDate());
578	        Person person = person(sheetId, claim.getPersonId());
579	        claim.setAmount(claim.getAmount().subtract(amount));
580	        claim.bind(false, null);
581	        Claim original = claims.saveAndFlush(claim);
582	        LocalDate dated = claim.getDate();
583	        Claim split = new Claim(sheetId, person.getId(), amount, dated,
584	                dueBy(sheetId, person, dated), claim.getNote(), null);
585	        split.setStatus(ClaimStatus.OPEN);
586	        split.setNumber(sheets.nextClaimNumber(sheetId, dated));
587	        split.setOpenedBy(user);
588	        split.setSplitFrom(original.getNumber());
589	        logStatus(sheetId, user, person, split);
590	        Claim added = claims.saveAndFlush(split);
591	        audit.recordOnCommit(record("CLAIM_SPLIT", sheetId, user, person, original)
592	                + " number=" + original.getNumber() + " into=" + added.getNumber());
593	        audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, added) + " number=" + added.getNumber());
594	        rollup.recordChanges(sheetId, user, before);
595	        return new Split(original, added);
596	    }
597	
598	    /** What a bulk open did: how many claims were opened and how many refused, and the claims opened. */
599	    public record BulkOpened(int opened, int refused, List<Claim> claims) {
600	    }
601	
602	    /**
603	     * Open the given claims together, in list order (the order people were added, newest claim
604	     * first within a person), so they are numbered in that order. A claim that cannot be opened
605	     * (not on the sheet, not DRAFT, dated inside a closed period, or due above the note threshold
606	     * with an empty note) is refused and left as it is.
607	     */
608	    @Transactional
609	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> ids) {
610	        List<Claim> selected = inListOrder(sheetId, ids);
611	        int refused = (int) ids.stream().distinct().count() - selected.size();
612	        List<Claim> opened = new ArrayList<>();
613	        boolean permitted = sheets.sheet(sheetId).permits("open", roles.roleOf(sheetId, user));
614	        for (Claim claim : selected) {
615	            if (!permitted || claim.getStatus() != ClaimStatus.DRAFT || periods.isClosed(sheetId, claim.getDate())
616	                    || needsNote(sheetId, person(sheetId, claim.getPersonId()), claim)) {
617	                refused++;
618	                continue;
619	            }
620	            opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
621	        }
622	        return new BulkOpened(opened.size(), refused, opened);
623	    }
624	
625	    /** What a bulk settle did: how many claims were settled (or made PENDING) and how many refused, and the claims changed. */
626	    public record BulkSettled(int settled, int refused, List<Claim> claims) {
627	    }
628	
629	    /**
630	     * Settle the given claims together, in list order (the order people were added, newest claim
631	     * first within a person), each by exactly the rules of settling one claim. A claim a clerk's
632	     * settle makes PENDING counts as settled; a claim that cannot be settled is refused and left
633	     * as it is.
634	     */
635	    @Transactional
636	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> ids) {
637	        List<Claim> selected = inListOrder(sheetId, ids);
638	        int refused = (int) ids.stream().distinct().count() - selected.size();
639	        List<Claim> settled = new ArrayList<>();
640	        for (Claim claim : selected) {
641	            try {
642	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
643	            } catch (ResponseStatusException refusedOne) {
644	                // every refusal is checked before the claim is changed, so it is left as it is
645	                refused++;
646	            }
647	        }
648	        return new BulkSettled(settled.size(), refused, settled);
649	    }
650	
651	    /** The given claims on the sheet in list order: people as added, newest claim first within a person. */
652	    private List<Claim> inListOrder(String sheetId, Collection<Long> ids) {
653	        Map<Long, Integer> personOrder = new HashMap<>();
654	        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
655	        for (int i = 0; i < listed.size(); i++) {
656	            personOrder.put(listed.get(i).getId(), i);
657	        }
658	        return ids.stream().distinct()
659	                .flatMap(id -> claims.findByIdAndSheetId(id, sheetId).stream())
660	                .sorted(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
661	                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
662	                .toList();
663	    }
664	
665	    /**
666	     * The due on a claim's amount at the rate for the person's grade in force on the claim's date,
667	     * rounded to the cent as the claim rounds (see {@link Rounding}), not raised to the floor (see {@link LateCharge});
668	     * null with no rate in force then.
669	     */
670	    public BigDecimal due(String sheetId, Person person, Claim claim) {
671	        Sheet sheet = sheets.sheet(sheetId);
672	        RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
673	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
674	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding))
675	                .orElse(null);
676	    }
677	
678	    /** The date a claim rounds by: its own, or for a correction that of the claim it corrects. */
679	    private LocalDate roundingDate(String sheetId, Claim claim) {
680	        if (!claim.isCorrection() || claim.getCorrects() == null) {
681	            return claim.getDate();
682	        }
683	        return Rounding.dateOf(claim, claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()));
684	    }
685	
686	    /** Log the claim's status as it is now: by the user, on the sheet's today, with its due as computed now. */
687	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
688	        claim.log(new ClaimLogEntry(claim.getStatus(), user, sheets.today(sheetId),
689	                dueText(charged(sheetId, person, claim))));
690	    }
691	
692	    private static String dueText(BigDecimal due) {
693	        return due == null ? "n/a" : due.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
694	    }
695	
696	    /** Whether a claim settling at the figure is above the proof threshold in force on its date and has no proofs. */
697	    private boolean needsProof(String sheetId, Claim claim, BigDecimal figure) {
698	        BigDecimal threshold = sheets.sheet(sheetId).proofThresholdOn(claim.getDate());
699	        return claim.getProofs() == 0 && figure != null && threshold != null && figure.compareTo(threshold) > 0;
700	    }
701	
702	    /** Whether a claim's due is above the note threshold in force on its date and its note is empty. */
703	    private boolean needsNote(String sheetId, Person person, Claim claim) {
704	        if (claim.getNote() != null && !claim.getNote().isBlank()) {
705	            return false;
706	        }
707	        BigDecimal threshold = sheets.sheet(sheetId).noteThresholdOn(claim.getDate());
708	        BigDecimal due = threshold == null ? null : charged(sheetId, person, claim);
709	        return due != null && due.compareTo(threshold) > 0;
710	    }
711	
712	    /** Whether the user is a clerk settling a claim whose figure is above the sheet's clerk limit. */
713	    private boolean aboveClerkLimit(String sheetId, String user, BigDecimal figure) {
714	        BigDecimal limit = sheets.clerkLimit(sheetId);
715	        return figure != null && limit != null && figure.compareTo(limit) > 0 && !isSteward(sheetId, user);
716	    }
717	
718	    private boolean isSteward(String sheetId, String user) {
719	        return Role.STEWARD.equals(roles.roleOf(sheetId, user));
720	    }
721	
722	    /**
723	     * The number a claim corrects: none unless its amount is negative, when it must name the number
724	     * of a SETTLED claim of the same person, else it is refused (400).
725	     */
726	    private String corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
727	        if (amount.signum() >= 0) {
728	            return null;
729	        }
730	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
731	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
732	        if (!settled) {
733	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
734	                    "A negative amount must correct a SETTLED claim of the same person, by its number.");
735	        }
736	        return corrects;
737	    }
738	
739	    /** Refuse (422) a claim dated after its person's retirement date. */
740	    private static void refuseIfRetired(Person person, LocalDate date) {
741	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
742	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
743	                    "That claim's date is after its person's retirement date.");
744	        }
745	    }
746	
747	    private Person person(String sheetId, long personId) {
748	        return people.findByIdAndSheetId(personId, sheetId)
749	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
750	    }
751	
752	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
753	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName() + " amount="
754	                + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString() + " date=" + claim.getDate();
755	    }
756	
757	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
758	        return date != null ? date : sheets.entryDate(sheetId);
759	    }
760	}
